CREATE OR REPLACE FUNCTION public.check_row_identity_change(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- A party's or type's id is also the id of the group that mirrors it, and
  -- interceptors put members into the group the id names: re-pointed, it could
  -- name any group (the Admin type's). Reads the request role.
  IF p_operation = 'UPDATE'
     AND current_setting('role', true) IN ('anon', 'authenticated')
     AND (
       (p_new->>'id') IS DISTINCT FROM (p_old->>'id')
       OR (p_new->>'companyId') IS DISTINCT FROM (p_old->>'companyId')
     ) THEN
    RAISE EXCEPTION 'A record''s id and company can only be changed by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_add_customer_account_to_group(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_operation != 'INSERT' THEN RETURN; END IF;

  -- A user is in a group once ("membership_groupId_memberUserId_key"). A
  -- membership left behind for this pair must not fail the parent insert.
  -- Only the customer's own organisation group, in this company: the id is caller-set.
  INSERT INTO "membership" ("groupId", "memberUserId")
  SELECT g.id, p_new->>'id'
  FROM "group" g
  WHERE g.id = p_new->>'customerId'
    AND g."isCustomerOrgGroup"
    AND g."companyId" = p_new->>'companyId'
  ON CONFLICT ("groupId", "memberUserId") DO NOTHING;
END;
$function$;

